// Enforce the repository's branch naming standard (see docs/release/BRANCHING.md).
// Allowed: feature/ bugfix/ hotfix/ refactor/ release/ bot branches.
const branch = process.env.BRANCH_NAME?.trim() ?? "";

if (branch === "main" || branch === "develop") {
  console.error(
    `Branch "${branch}" is protected and cannot be a PR head branch.`,
  );
  process.exit(1);
}

// Bot branches are generated by automation (their names can contain uppercase
// characters and mixed separators, e.g.
// dependabot/github_actions/SonarSource/sonarqube-scan-action-8.5.0). Rule 5 of
// BRANCHING.md exempts them from the kebab-case slug rule, so only the bot
// prefix is checked here. Human branches remain subject to the strict pattern.
const botBranch = /^(dependabot|renovate)\/.+/;
if (botBranch.test(branch)) {
  console.log(`Bot branch name accepted: ${branch}`);
  process.exit(0);
}

const allowed =
  /^(feature|bugfix|hotfix|refactor|release)\/[a-z0-9][a-z0-9._/-]*$/;

if (!allowed.test(branch)) {
  console.error(
    `Branch "${branch}" does not follow the naming convention. Use one of: feature/<slug>, bugfix/<slug>, hotfix/<slug>, refactor/<slug>, or a dependabot/renovate/ bot branch (see docs/release/BRANCHING.md).`,
  );
  process.exit(1);
}

console.log(`Branch name accepted: ${branch}`);
